// The structured ambiguous return lets callers render a styled failure
// block (with each match's timestamp/session) without re-resolving the
// matches themselves.
func resolveCommitUnambiguous(repo *git.Repository, ref string) (plumbing.Hash, []plumbing.Hash, error) {
	hash, err := repo.ResolveRevision(plumbing.Revision(ref))
	if err != nil {
		return plumbing.ZeroHash, nil, err //nolint:wrapcheck // caller contextualizes
	}
	matches := commitHashesWithPrefix(repo, ref)
	if len(matches) <= 1 {
		return *hash, nil, nil
	}
	return plumbing.ZeroHash, matches, errAmbiguousCommitPrefix
}

// abbreviateCommitHash returns the shortest prefix of hash unique among
// commit objects in the repo, matching git's --abbrev-commit auto-growth
// so displayed short SHAs stay unambiguous as the repo grows. Falls back
// to a fixed 12-char prefix if the storer doesn't support fast prefix
// lookup, or to the full hash if somehow never unique.
func abbreviateCommitHash(repo *git.Repository, hash plumbing.Hash) string {
	full := hash.String()
	for length := 7; length < len(full); length++ {
		matches := commitHashesWithPrefix(repo, full[:length])
		if matches == nil {
			return full[:12]
		}
		if len(matches) <= 1 {
			return full[:length]
		}
	}
	return full
}

// associatedCommit holds information about a git commit associated with a checkpoint.
type associatedCommit struct {
	SHA      string
	ShortSHA string
	Message  string
	Author   string
	Email    string
	Date     time.Time
}

func newExplainCmd() *cobra.Command {
	var sessionFlag string
	var commitFlag string
	var checkpointFlag string
	var noPagerFlag bool
	var shortFlag bool
	var fullFlag bool
	var rawTranscriptFlag bool
	var generateFlag bool
	var forceFlag bool
	var searchAllFlag bool
	var jsonFlag bool
	var transcriptFlag bool
	var summaryTimeoutSecondsFlag int
	sessionIndex := -1
	listLimit := 0 // 0 means "use default (branchCheckpointsLimit)"

	cmd := &cobra.Command{
		Use:   "explain [checkpoint-id | commit-sha]",
		Short: "Explain a session, commit, or checkpoint",
		Long: `Explain provides human-readable context about sessions, commits, and checkpoints.

Use this command to understand what happened during agent-driven development,
either for self-review or to understand a teammate's work.

By default, shows checkpoints on the current branch. Pass a checkpoint ID or
commit SHA as a positional argument to explain a specific item, or use flags.

Viewing specific items:
  entire checkpoint explain <id-or-sha>           Auto-detects checkpoint ID or commit SHA
  entire checkpoint explain --checkpoint <id>     Force interpretation as checkpoint ID
  entire checkpoint explain --commit <ref>        Force interpretation as commit ref

Filtering the list view:
  --session      Filter checkpoints by session ID (or prefix)

Output verbosity levels (when explaining a specific item):
  Default:         Detailed view with scoped prompts (ID, session, tokens, intent, prompts, files)
  --short          Summary only (ID, session, timestamp, tokens, intent)
  --full           Parsed full transcript (all prompts/responses from entire session)
  --raw-transcript Raw transcript file (JSONL format)

Machine-readable export modes (additive surface for external consumers):
  --json           Metadata-only JSON. Lists checkpoints when no target is given;
                   emits a single checkpoint envelope when a target is supplied.
                   Transcript bytes are NEVER embedded in the JSON envelope.
  --transcript     Stream stored checkpoint transcript bytes (JSONL) to stdout
                   for the selected session. Same bytes as --raw-transcript
                   while checkpoints v1 is the checkpoint store.
  --session-index  Pick a session within a multi-session checkpoint (0-based).
                   Defaults to the latest session. Only meaningful with
                   --transcript or --raw-transcript.
  --limit          Cap the number of checkpoints returned by the list view.
                   Defaults to 100. When the cap is hit, a stderr note
                   says how many were skipped. Only meaningful with --json.

Summary generation:
  --generate    Generate an AI summary for the checkpoint
  --force       Regenerate even if a summary already exists (requires --generate)

Performance options:
  --search-all  Remove branch/depth limits when searching for commits (may be slow)

Checkpoint detail view shows:
  - Author of the checkpoint
  - Associated git commits that reference the checkpoint
  - Prompts and responses from the session

Note: --session filters the list view; the positional arg, --commit, and --checkpoint are mutually exclusive.`,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most 1 argument (checkpoint ID or commit SHA), received %d\nHint: use --session to filter the list view, or pass a single checkpoint ID / commit SHA", len(args))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Check if Entire is disabled
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}

			// Only initialize logging when inside a git worktree to avoid
			// creating .entire/logs/ in arbitrary directories.
			if _, err := paths.WorktreeRoot(cmd.Context()); err == nil {
				logging.SetLogLevelGetter(GetLogLevel)
				if err := logging.Init(cmd.Context(), ""); err == nil {
					defer logging.Close()
				}
			}

			// Positional arg is mutually exclusive with --checkpoint, --commit, --session
			var positional string
			if len(args) > 0 {
				positional = args[0]
				if checkpointFlag != "" || commitFlag != "" || sessionFlag != "" {
					return errors.New("cannot combine positional argument with --checkpoint, --commit, or --session")
				}
			}

			// --generate and --raw-transcript need a specific target — either the
			// positional arg, --checkpoint/-c, or --commit (which forwards to
			// the checkpoint path via the commit's Entire-Checkpoint trailer).
			hasCheckpointTarget := checkpointFlag != "" || commitFlag != "" || positional != ""
			if generateFlag && !hasCheckpointTarget {
				return errors.New("--generate requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
			}
			if forceFlag && !generateFlag {
				return errors.New("--force requires --generate flag")
			}
			if rawTranscriptFlag && !hasCheckpointTarget {
				return errors.New("--raw-transcript requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
			}
			if transcriptFlag && !hasCheckpointTarget {
				return errors.New("--transcript requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
			}
			if cmd.Flags().Changed("session-index") {
				if !transcriptFlag && !rawTranscriptFlag {
					return errors.New("--session-index only applies with --transcript or --raw-transcript")
				}
				if sessionIndex < 0 {
					return errors.New("--session-index must be non-negative")
				}
			}
			if cmd.Flags().Changed("limit") {
				if !jsonFlag {
					return errors.New("--limit only applies with --json")
				}
				if listLimit <= 0 {
					return errors.New("--limit must be positive")
				}
			}
			// --summary-timeout-seconds only makes sense with --generate.
			if cmd.Flags().Changed("summary-timeout-seconds") {
				if !generateFlag {
					return errors.New("--summary-timeout-seconds only applies with --generate")
				}
				if summaryTimeoutSecondsFlag < 0 {
					return errors.New("--summary-timeout-seconds must be non-negative")
				}
			}

			// Export modes — emit machine-readable output and skip the prose pipeline.
			// --raw-transcript also routes here when --session-index is explicit; the
			// legacy raw-transcript path (with spinner + prefetch) handles the default
			// case where the caller wants the latest session.
			rawWithSessionIndex := rawTranscriptFlag && cmd.Flags().Changed("session-index")
			if jsonFlag || transcriptFlag || rawWithSessionIndex {
				return runExplainExport(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), explainExportOptions{
					sessionFilter:  sessionFlag,
					commitRef:      commitFlag,
					checkpointFlag: checkpointFlag,
					target:         positional,
					json:           jsonFlag,
					transcript:     transcriptFlag,
					rawTranscript:  rawTranscriptFlag,
					sessionIndex:   sessionIndex,
					listLimit:      listLimit,
				})
			}

			// Convert short flag to verbose (verbose = !short)
			verbose := !shortFlag
			return runExplain(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionFlag, commitFlag, checkpointFlag, positional, noPagerFlag, verbose, fullFlag, rawTranscriptFlag, generateFlag, forceFlag, searchAllFlag, summaryTimeoutSecondsFlag)
		},
	}

	cmd.Flags().StringVar(&sessionFlag, "session", "", "Filter checkpoints by session ID (or prefix)")
	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref, \"commit-ish\")")
	cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Explain a specific checkpoint (ID or prefix)")
	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
	cmd.Flags().BoolVarP(&shortFlag, "short", "s", false, "Show summary only (omit prompts and files)")
	cmd.Flags().BoolVar(&fullFlag, "full", false, "Show full parsed transcript (all prompts/responses)")
	cmd.Flags().BoolVar(&rawTranscriptFlag, "raw-transcript", false, "Show raw transcript file (JSONL format)")
	cmd.Flags().BoolVar(&generateFlag, "generate", false, "Generate an AI summary for the checkpoint")
	cmd.Flags().BoolVar(&forceFlag, "force", false, "Regenerate summary even if one already exists (requires --generate)")
	cmd.Flags().BoolVar(&searchAllFlag, "search-all", false, "Search all commits (no branch/depth limit, may be slow)")
	cmd.Flags().BoolVar(&jsonFlag, "json", false, "Output metadata as JSON (no transcript bytes)")
	cmd.Flags().BoolVar(&transcriptFlag, "transcript", false, "Stream stored checkpoint transcript bytes to stdout")
	cmd.Flags().IntVar(&sessionIndex, "session-index", -1, "Session index within a multi-session checkpoint (0-based, defaults to latest)")
	cmd.Flags().IntVar(&listLimit, "limit", 0, "Cap the list view at N checkpoints (default: 100). Only meaningful with --json.")
	cmd.Flags().IntVar(&summaryTimeoutSecondsFlag, "summary-timeout-seconds", 0, "Hard deadline in seconds for --generate summary generation; overrides summary_timeout_seconds setting. 0 = use setting; if setting is also unset or 0, no automatic deadline applies.")

	// Verbosity / transcript output modes are mutually exclusive
	cmd.MarkFlagsMutuallyExclusive("short", "full", "raw-transcript", "transcript", "json")
	// --generate and --raw-transcript are incompatible (summary would be generated but not shown)
	cmd.MarkFlagsMutuallyExclusive("generate", "raw-transcript")
	// --generate is a write op; export modes are reader-only
	cmd.MarkFlagsMutuallyExclusive("generate", "json")
	cmd.MarkFlagsMutuallyExclusive("generate", "transcript")

	return cmd
}

// runExplain routes to the appropriate explain function based on flags and the
// optional positional target.
func runExplain(ctx context.Context, w, errW io.Writer, sessionID, commitRef, checkpointID, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	// Count mutually exclusive flags (--commit and --checkpoint are mutually exclusive)
	// --session is now a filter for the list view, not a separate mode
	flagCount := 0
	if commitRef != "" {
		flagCount++
	}
	if checkpointID != "" {
		flagCount++
	}
	// If --session is combined with --commit or --checkpoint, that's still an error
	if sessionID != "" && flagCount > 0 {
		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
	}
	if flagCount > 1 {
		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
	}

	// Route to appropriate handler
	if target != "" {
		return runExplainAuto(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}
	if commitRef != "" {
		return runExplainCommit(ctx, w, errW, commitRef, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}
	if checkpointID != "" {
		return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
	}

	// Default or with session filter: show list view (optionally filtered by session)
	return runExplainBranchWithFilter(ctx, w, errW, noPager, sessionID)
}

// explainTargetNotFoundError reports that the requested checkpoint target
// matched no committed or temporary checkpoint. It unwraps to
// checkpoint.ErrCheckpointNotFound so callers' errors.Is contracts keep
// working, while runExplainAuto can distinguish this resolution miss from a
// failure AFTER a successful match that happens to wrap the same sentinel
// (e.g. "failed to save summary: checkpoint not found" from a backfill
// against a backend missing the checkpoint) — those must surface verbatim,
// not be masked by the commit fallback's "no checkpoint or commit found".
type explainTargetNotFoundError struct{ target string }

func (e *explainTargetNotFoundError) Error() string {
	return fmt.Sprintf("%s: %s", checkpoint.ErrCheckpointNotFound, e.target)
}

func (e *explainTargetNotFoundError) Unwrap() error { return checkpoint.ErrCheckpointNotFound }

// shouldFallBackToCommitResolution reports whether the checkpoint path's error
// means "the target matched nothing", the only outcome that may fall through
// to git commit resolution.
func shouldFallBackToCommitResolution(err error) bool {
	var targetMiss *explainTargetNotFoundError
	return errors.As(err, &targetMiss)
}

// runExplainAuto resolves a positional target as either a checkpoint ID
// (or prefix) or a git commit ref. Ordering: checkpoint path first (which
// also handles shadow-branch temp checkpoints), falling back to commit
// resolution only on the target-miss error (explainTargetNotFoundError).
// --generate runs an ambiguity pre-check to avoid writing a summary to the
// wrong checkpoint on short-prefix collisions.
func runExplainAuto(ctx context.Context, w, errW io.Writer, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
	stop := startSpinner(errW, "Loading checkpoints")
	lookup, lookupErr := newExplainCheckpointLookup(ctx)
	stop(false)
	if lookup != nil {
		defer lookup.Close()
	}
	if generate {

package cli

import (
	"context"
	"fmt"
	"os/exec"
	"regexp"
	"sort"
	"strings"

	"charm.land/huh/v2"
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/internal/coreapi"
)

// mirrorCloneRefRe parses the clone-ref shape `entire repo clone` accepts:
// the `/gh/<owner>/<repo>` path of a mirror's clone URL, with or without the
// leading slash. owner/repo reuse the GitHub identifier charsets from
// parseGitHubURL so the same metacharacter vectors are closed at the boundary
// (owner/repo flow unescaped into the synthesised entire:// clone URL).
var mirrorCloneRefRe = regexp.MustCompile(`^/?gh/` + gitHubOwnerPat + `/` + gitHubRepoPat + `$`)

// mirrorCloneProviderGitHub is the upstream provider the `gh` path token maps to
// — the value the control plane records and the list API filters on. Kept local
// to the clone path so the provider mapping is self-contained rather than
// borrowing a constant named for an unrelated (checkpoint) concern.
const mirrorCloneProviderGitHub = "github"

// entireCloneURLScheme is the scheme of a full mirror clone URL, which
// git-remote-entire resolves directly. Such a URL already names the cluster, so
// `repo clone` passes it through to `git clone` untouched.
const entireCloneURLScheme = "entire://"

// isEntireCloneURL reports whether ref is a full entire:// clone URL (vs. the
// `/gh/<owner>/<repo>` shorthand that needs a mirror lookup).
func isEntireCloneURL(ref string) bool {
	return strings.HasPrefix(strings.TrimSpace(ref), entireCloneURLScheme)
}

// mirrorCloneURL synthesizes the entire:// clone URL for a GitHub mirror from
// its cluster host and owner/repo — the form `git clone` accepts, which the
// mirror list API doesn't return. Shared by the mirror table view (mirrorRow)
// and `repo clone` so the wire format lives in one place.
//
// HARDCODED ASSUMPTIONS (revisit if either stops holding):
//   - The provider path segment is fixed to "gh". Mirrors are GitHub-only
//     today; the list/index API (RepoPlacement) records no provider, so there
//     is nothing to key off. If a non-GitHub provider ever lands, this must
//     take a provider argument or the URL will lie.
//   - This is a client-side RECONSTRUCTION, not the server's canonical URL.
//     The list index gives only a cluster slug, so callers resolve slug->host
//     (clusterHostBySlug, via a separate ListClusters call) before calling
//     this. If /repos ever returns the clone URL (or host+provider) directly,
//     drop this synthesis and that extra round-trip.
func mirrorCloneURL(host, owner, repo string) string {
	return fmt.Sprintf("%s%s/gh/%s/%s", entireCloneURLScheme, host, owner, repo)
}

// parseMirrorCloneRef turns a clone ref like `/gh/entirehq/entire-api` into the
// API provider ("github") and the lowercased owner/repo. The `gh` token is the
// path provider used in entire:// clone URLs; it maps to the "github" upstream
// provider the control plane records.
func parseMirrorCloneRef(ref string) (provider, owner, repo string, err error) {
	m := mirrorCloneRefRe.FindStringSubmatch(strings.TrimSpace(ref))
	if m == nil {
		return "", "", "", fmt.Errorf("expected gh/<owner>/<repo> (leading slash optional), got %q", ref)
	}
	owner, repo = strings.ToLower(m[1]), strings.ToLower(m[2])
	if gitHubDotOnlyRe.MatchString(repo) {
		return "", "", "", fmt.Errorf("repo cannot be dot-only: %s", ref)
	}
	return mirrorCloneProviderGitHub, owner, repo, nil
}

func newRepoCloneCmd() *cobra.Command {
	var cluster string
	cmd := &cobra.Command{
		Use:   "clone <repo> [target-dir]",
		Short: "Clone a mirrored repository",
		Long: "Clone a GitHub mirror by its `/gh/<owner>/<repo>` ref, or by a full " +
			"`entire://<cluster>/gh/<owner>/<repo>` clone URL.\n\n" +
			"With a `/gh/<owner>/<repo>` ref, looks up where the repo is mirrored: if " +
			"it's on a single cluster, clones it directly; if it's mirrored on more " +
			"than one, prompts you to pick which to clone from (or pass --cluster to " +
			"choose non-interactively).\n\n" +
			"A full `entire://` URL already names the cluster, so it's passed straight " +
			"through to `git clone` with no lookup (and --cluster is ignored). The " +
			"optional [target-dir] is passed through to `git clone` either way.",
		Example: "  entire repo clone /gh/entirehq/entire-api\n" +
			"  entire repo clone /gh/entirehq/entire-api ./entire-api\n" +
			"  entire repo clone /gh/entirehq/entire-api --cluster aws-us-east-2.entire.io\n" +
			"  entire repo clone entire://aws-us-east-2.entire.io/gh/entirehq/entire-api",
		Args: cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			cmd.SilenceUsage = true
			// Trim once up front so the entire:// detection and the value forwarded
			// to git clone agree (the shorthand path trims inside parseMirrorCloneRef).
			ref := strings.TrimSpace(args[0])
			var targetDir string
			if len(args) > 1 {
				targetDir = args[1]
			}

			// A full entire:// clone URL already embeds the cluster host (it's what
			// --cluster would otherwise resolve to), so pass it verbatim to git clone
			// — no mirror lookup or cluster resolution. --cluster is irrelevant here.
			//
			// Deliberately NOT run through validateClusterHost: this is a raw URL the
			// user typed, forwarded to `git clone` exactly as given (the whole point
			// of this branch), so it's equivalent to running `git clone entire://…`
			// directly. The validateClusterHost guard applies on the shorthand path
			// where we *synthesize* the URL from a --cluster flag or an API-supplied
			// host — values that flow into the STS audience under our own construction.
			if isEntireCloneURL(ref) {
				return runGitClone(cmd.Context(), cmd, ref, targetDir)
			}

			// provider is always "github" for the /gh/ shorthand; the pull-gated
			// resolver pins the provider itself, so it's not threaded through.
			_, owner, repo, err := parseMirrorCloneRef(ref)
			if err != nil {
				return fmt.Errorf("invalid <repo>: %w", err)
			}

			var placements []coreapi.ResolvedPlacement
			lister := func(ctx context.Context, c *coreapi.Client) error {
				ps, err := resolvePullablePlacements(ctx, c, owner, repo)
				if err != nil {
					return err
				}
				placements = ps
				return nil
			}
			// An explicit --cluster may name a cluster in a different federation
			// than the active context, whose mirrors the active-context core can't
			// see (the original bug: cloning a royalcanin.partial.to mirror while a
			// different context is active failed with "not mirrored on ..."). Dial
			// the core fronting that cluster — discovered from its well-known and
			// authenticated with the matching local context, the same path
			// `mirror create <url> [cluster]` uses — so the lookup resolves against
			// the right federation. With no --cluster, list from the active context.
			runWithCore := runCore
			if cluster != "" {
				if err := validateClusterHost(cluster); err != nil {
					return fmt.Errorf("invalid --cluster: %w", err)
				}
				runWithCore = func(cmd *cobra.Command, fn func(context.Context, *coreapi.Client) error) error {
					return runCoreForCluster(cmd, cluster, fn)
				}
			}
			if err := runWithCore(cmd, lister); err != nil {
				return err
			}

			if len(placements) == 0 {
				return fmt.Errorf("no mirror found for /gh/%s/%s; run 'entire repo mirror create github.com/%s/%s' to onboard it", owner, repo, owner, repo)
			}

			chosen, err := selectCloneTarget(cmd, placements, cluster)
			if err != nil {
				return err
			}

			// chosen.ClusterHost is server-provided, but it's interpolated into the
			// entire:// clone URL just like the user-supplied --cluster, so apply the
			// same anti-token-leak guard (validateClusterHost) before building it —
			// defense-in-depth against a malformed host reaching git / the STS audience.
			if err := validateClusterHost(chosen.ClusterHost); err != nil {
				return fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
			}
			cloneURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
			return runGitClone(cmd.Context(), cmd, cloneURL, targetDir)
		},
	}
	cmd.Flags().StringVar(&cluster, "cluster", "", "Cluster host to clone from when the repo is mirrored on more than one (may belong to another auth context)")
	return cmd
}

// mirrorLister is the subset of the control-plane client listMirrorsForRepo
// needs. Narrowing to an interface lets callers (e.g. the experts cell-target
// resolver) inject a fake control plane in tests; *coreapi.Client satisfies it.
type mirrorLister interface {
	ListMirrors(ctx context.Context, params coreapi.ListMirrorsParams) (*coreapi.ListMirrorsOutputBody, error)
}

// listMirrorsForRepo returns every mirror placement of one upstream repo across
// clusters. The list API filters by provider+owner server-side but has no repo
// filter, so the repo match is applied client-side (owner is already lowercased
// to match what the server persists).
func listMirrorsForRepo(ctx context.Context, c mirrorLister, provider, owner, repo string) ([]coreapi.Mirror, error) {
	all, err := fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Mirror, string, error) {
		params := coreapi.ListMirrorsParams{
			Provider: coreapi.NewOptString(provider),
			Owner:    coreapi.NewOptString(owner),
		}
		if cursor != "" {
			params.PageToken = coreapi.NewOptString(cursor)
		}
		out, err := c.ListMirrors(ctx, params)
		if err != nil {
			return nil, "", fmt.Errorf("list mirrors: %w", err)
		}
		return out.Mirrors, out.NextPageToken.Or(""), nil
	})
	if err != nil {
		return nil, err
	}
	matched := make([]coreapi.Mirror, 0, len(all))
	for _, m := range all {
		if strings.EqualFold(m.Repo, repo) {
			matched = append(matched, m)
		}
	}
	return matched, nil
}

// resolvePullablePlacements returns every cluster placement of one GitHub
// upstream the caller may pull (clone). It backs `repo clone /gh/<owner>/<repo>`
// and deliberately differs from listMirrorsForRepo: that reads the
// affiliation-scoped mirror list (repo#list), which omits public mirrors the
// caller holds no grant on, so the shorthand used to fail on a public repo that
// clones fine by full entire:// URL. This hits the pull-gated /mirrors/placements
// endpoint instead — the same authority the clone's STS exchange enforces — so
// anything clonable resolves, public or private-with-grant.
//
// owner/repo arrive already lowercased from parseMirrorCloneRef; the server
// matches case-insensitively regardless. An empty result means not mirrored or
// not pullable, and the caller surfaces that.
func resolvePullablePlacements(ctx context.Context, c *coreapi.Client, owner, repo string) ([]coreapi.ResolvedPlacement, error) {
	out, err := c.ResolveMirrorPlacements(ctx, coreapi.ResolveMirrorPlacementsParams{
		Provider: coreapi.ResolveMirrorPlacementsProviderGithub,
		Owner:    owner,
		Repo:     repo,
	})
	if err != nil {
		return nil, fmt.Errorf("resolve mirror placements: %w", err)
	}
	return out.Placements, nil
}

// placementPicker adapts selectPlacement's messages to the calling verb. The
// picker logic is identical for every consumer (dedupe by host, honor an
// explicit selector, prompt only when there's a real choice); only the words
// differ, so they're passed in rather than duplicated per command.
type placementPicker struct {
	// selector names the non-interactive way to choose a cluster, as the user
	// would type it (e.g. `--cluster`). Interpolated into the no-terminal error
	// so the pointer names a flag the calling command actually accepts.
	selector string
	// title is the interactive single-select's prompt.
	title string
	// action names the operation in the cancellation message, capitalized
	// ("Clone", "Remote update") — handleFormCancellation prints
	// "<action> cancelled."
	action string
}

// selectCloneTarget resolves which mirror placement to clone from, with the
// clone verb's wording. See selectPlacement for the selection rules.
func selectCloneTarget(cmd *cobra.Command, placements []coreapi.ResolvedPlacement, clusterFlag string) (coreapi.ResolvedPlacement, error) {
	return selectPlacement(cmd, placements, clusterFlag, placementPicker{
		selector: "--cluster",
		title:    "This repo is mirrored on more than one cluster — pick one to clone from",
		action:   "Clone",
	})
}

// selectPlacement resolves which mirror placement a verb should act on. With one
// placement it returns it directly. With an explicit clusterSel it picks the
// matching one (or errors listing the available hosts). With more than one and no
// selector it prompts interactively, failing fast with a p.selector pointer when
// there's no terminal.
func selectPlacement(cmd *cobra.Command, placements []coreapi.ResolvedPlacement, clusterSel string, p placementPicker) (coreapi.ResolvedPlacement, error) {
	// Dedupe by cluster host: one placement per cluster is what a caller acts on,
	// and the same host appearing twice would only confuse the picker. Key on the
	// case-folded host — DNS is case-insensitive, so a selector value differing
	// only in case from the API's ClusterHost must still match (the alternative is
	// a misleading "not mirrored on ..." after a successful lookup + dial).
	byHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
	hosts := make([]string, 0, len(placements))
	for _, p := range placements {
		key := strings.ToLower(p.ClusterHost)
		if _, seen := byHost[key]; seen {
			continue
		}
		byHost[key] = p
		hosts = append(hosts, key)
	}
	sort.Strings(hosts)

	if clusterSel != "" {
		match, ok := byHost[strings.ToLower(strings.TrimSpace(clusterSel))]
		if !ok {
			return coreapi.ResolvedPlacement{}, fmt.Errorf("repo is not mirrored on %q; available: %s", clusterSel, strings.Join(hosts, ", "))
		}
		return match, nil
	}

	if len(hosts) == 1 {
		return byHost[hosts[0]], nil
	}

	if !interactive.CanPromptInteractively() {
		return coreapi.ResolvedPlacement{}, fmt.Errorf("repo is mirrored on %d clusters; pass %s to choose one of: %s", len(hosts), p.selector, strings.Join(hosts, ", "))
	}

	options := make([]huh.Option[string], len(hosts))
	for i, h := range hosts {
		options[i] = huh.NewOption(mirrorCellLabel(byHost[h]), h)
	}
	var selected string
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title(p.title).
				Options(options...).
				Value(&selected),
		),
	)
	if err := form.RunWithContext(cmd.Context()); err != nil {
		// handleFormCancellation prints "<action> cancelled." and returns nil for a
		// Ctrl+C / cancelled-context abort. Surface that as a SilentError so the
		// caller stops instead of falling through to act on a zero-value target
		// (the `entire:///gh/...` empty-host bug) without main.go reprinting the
		// message handleFormCancellation already wrote; a real form error propagates.
		if cerr := handleFormCancellation(cmd.ErrOrStderr(), p.action, err); cerr != nil {
			return coreapi.ResolvedPlacement{}, cerr
		}
		return coreapi.ResolvedPlacement{}, NewSilentError(fmt.Errorf("%s cancelled", strings.ToLower(p.action)))
	}
	match, ok := byHost[selected]
	if !ok {
		// The form succeeded but handed back a host that is not on offer. Nothing
		// has been printed here, so this must NOT be a SilentError — main.go
		// suppresses those, and the command would exit non-zero with no message.
		return coreapi.ResolvedPlacement{}, fmt.Errorf("no cluster selected from the %d offered", len(hosts))
	}
	return match, nil
}

// mirrorCellLabel is the human label for a mirror placement in the clone picker:
// the physical cell and jurisdiction when known, always anchored by the cluster
// host that goes into the clone URL.
func mirrorCellLabel(p coreapi.ResolvedPlacement) string {
	cell := strings.TrimSpace(p.Cell.Or(""))
	jur := strings.TrimSpace(p.Jurisdiction.Or(""))
	switch {
	case cell != "" && jur != "":
		return fmt.Sprintf("%s (%s) — %s", cell, jur, p.ClusterHost)
	case cell != "":
		return fmt.Sprintf("%s — %s", cell, p.ClusterHost)
	default:
		return p.ClusterHost
	}
}

// runGitClone shells out to `git clone <cloneURL> [target-dir]`, wiring the
// child's stdio through so git-remote-entire's auth prompts and clone progress
// reach the user. A clone failure is wrapped as a SilentError: git already
// printed its own diagnostics, so main.go shouldn't reprint the wrapper.
func runGitClone(ctx context.Context, cmd *cobra.Command, cloneURL, targetDir string) error {
	args := []string{"clone", cloneURL}
	if targetDir != "" {
		args = append(args, targetDir)
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "Cloning %s\n", cloneURL)
	gitCmd := exec.CommandContext(ctx, "git", args...)
	gitCmd.Stdin = cmd.InOrStdin()
	gitCmd.Stdout = cmd.OutOrStdout()
	gitCmd.Stderr = cmd.ErrOrStderr()
	if err := gitCmd.Run(); err != nil {
		return NewSilentError(fmt.Errorf("git clone failed: %w", err))
	}
	return nil
}

package checkpoint

import (
	"fmt"
	"strings"

	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// CheckpointRefPrefix is the namespace under which the git-refs backend stores
// one ref per checkpoint: refs/entire/checkpoints/<shard>/<id>. Each ref points
// at a checkpoint commit whose tree root is that checkpoint's contents. This is
// distinct from the git-branch backend's single entire/checkpoints/v1 branch.
const CheckpointRefPrefix = "refs/entire/checkpoints/"

// RefName returns the per-checkpoint git ref for a checkpoint ID:
// refs/entire/checkpoints/<shard>/<id>, where <shard> is id.ShardFor() (the
// last two characters of the ID for both legacy hex and ULID formats). The full
// ID is always the leaf, so the ref round-trips through ParseRef.
//
// It errors on an empty or unrecognized checkpoint ID rather than returning a
// malformed ref (e.g. "refs/entire/checkpoints//"), so callers at trust
// boundaries — and future ones — can't silently push, fetch, or look up a bad
// ref.
func RefName(cid id.CheckpointID) (plumbing.ReferenceName, error) {
	if cid.Kind() == id.KindUnknown {
		return "", fmt.Errorf("cannot build checkpoint ref: invalid checkpoint ID %q", cid)
	}
	return plumbing.ReferenceName(CheckpointRefPrefix + cid.ShardFor() + "/" + cid.String()), nil
}

// ParseRef extracts the checkpoint ID from a per-checkpoint ref name,
// reporting whether name is a well-formed checkpoint ref. A ref is well-formed
// when it has the CheckpointRefPrefix, exactly a <shard>/<id> tail, and the
// shard matches the ID's own ShardFor — so refs the resolver did not write
// (mismatched shard, extra path segments) are rejected rather than silently
// resolved to the wrong bucket. It does not require the ID to be a recognized
// kind, so a future ID format still parses as long as it shards consistently.
func ParseRef(name plumbing.ReferenceName) (id.CheckpointID, bool) {
	s := name.String()
	tail, ok := strings.CutPrefix(s, CheckpointRefPrefix)
	if !ok {
		return id.EmptyCheckpointID, false
	}
	shard, rest, ok := strings.Cut(tail, "/")
	if !ok || shard == "" || rest == "" {
		return id.EmptyCheckpointID, false
	}
	// Reject extra path segments: the tail must be exactly <shard>/<id>.
	if strings.Contains(rest, "/") {
		return id.EmptyCheckpointID, false
	}
	cid := id.CheckpointID(rest)
	if cid.ShardFor() != shard {
		return id.EmptyCheckpointID, false
	}
	return cid, true
}

