   440→// prepareCrossRepoExplain resolves --repo/--cluster and, when the target repo
   441→// differs from the cwd repo, fetches the checkpoint's per-checkpoint ref from
   442→// that repo's Entire mirror into the cwd repo's object store. After a nil
   443→// return, the normal explain flow resolves the checkpoint as if it were local.
   444→// When --repo names the cwd repo it is a no-op (behavior identical to no flag).
   445→func prepareCrossRepoExplain(cmd *cobra.Command, repoFlag, clusterFlag, target string) error {
   446→	ref, err := parseExplainRepoFlag(repoFlag)
   447→	if err != nil {
   448→		return err
   449→	}
   450→	owner, repoName := ref.owner, ref.repo
   451→	if ref.repoID != "" {
   452→		owner, repoName, err = resolveExplainRepoID(cmd, ref.repoID)
   453→		if err != nil {
   454→			return err
   455→		}
   456→	}
   457→	if explainRepoIsCurrent(cmd.Context(), owner, repoName) {
   458→		return nil
   459→	}
   460→	cmd.SilenceUsage = true
   461→	// A prefix cannot name a per-checkpoint ref, so cross-repo needs the full ID.
   462→	cid, err := id.NewCheckpointID(target)
   463→	if err != nil {
   464→		return fmt.Errorf("--repo requires a full checkpoint ID (12-char hex or 26-char ULID); a prefix cannot be resolved cross-repo: %w", err)
   465→	}
   466→	url, err := resolveExplainRepoFetchURL(cmd, owner, repoName, clusterFlag)
   467→	if err != nil {
   468→		return err
   469→	}
   470→	return fetchCrossRepoCheckpoint(cmd.Context(), cmd.ErrOrStderr(), url, owner+"/"+repoName, cid)
   471→}
   472→
   473→// fetchCrossRepoCheckpoint fetches cid's per-checkpoint ref
   474→// (refs/entire/checkpoints/<shard>/<id>) from url into the cwd repo's object
   475→// store. Separated from URL resolution so tests can exercise the fetch +
   476→// explain flow against a file:// remote without the core API or
   477→// git-remote-entire.
   478→func fetchCrossRepoCheckpoint(ctx context.Context, errW io.Writer, url, ownerRepo string, cid id.CheckpointID) error {
   479→	refName, err := checkpoint.RefName(cid)
   480→	if err != nil {
   481→		// cid is validated by the caller, so this is defensive only.
   482→		return err //nolint:wrapcheck // in-package error carries full context
   483→	}
   484→	stop := startSpinner(errW, "Fetching checkpoint from "+ownerRepo)
   485→	fetchErr := remote.FetchCheckpointRefFrom(ctx, url, refName)
   486→	stop(fetchErr == nil)
   487→	if fetchErr == nil {
   488→		return nil
   489→	}
   490→	if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
   491→		return fmt.Errorf("checkpoint %s not found in %s's mirror; repos using the legacy branch-based checkpoint store (or an external checkpoint_remote) are not supported cross-repo yet", cid, ownerRepo)
   492→	}
   493→	return fmt.Errorf("fetch checkpoint %s from %s: %w", cid, ownerRepo, fetchErr)
   494→}
