   332→// explainRepoRef is a parsed `explain --repo` value: either an owner/name slug
   333→// (possibly given with a gh/ prefix) or a raw repo ULID that still needs a
   334→// control-plane lookup to become owner/name.
   335→type explainRepoRef struct {
   336→	owner, repo string // owner/name form (lowercased)
   337→	repoID      string // bare-ULID form
   338→}
   339→
   340→// parseExplainRepoFlag parses the --repo flag value. Accepted shapes:
   341→// `owner/name`, `gh/owner/name` (leading slash optional), or a bare repo ULID.
   342→// owner/name reuse the GitHub charset validation of the mirror clone-ref
   343→// parser and come back lowercased, matching what the control plane persists.
   344→func parseExplainRepoFlag(value string) (explainRepoRef, error) {
   345→	v := strings.TrimSpace(value)
   346→	if v == "" {
   347→		return explainRepoRef{}, errors.New("--repo requires a value: owner/name, gh/owner/name, or a repo ID")
   348→	}
   349→	if strings.Contains(v, "/") {
   350→		// Normalize owner/name to the gh/owner/name clone-ref shape so
   351→		// parseMirrorCloneRef's charset validation applies to both forms.
   352→		ref := strings.TrimPrefix(v, "/")
   353→		if !strings.HasPrefix(ref, "gh/") {
   354→			ref = "gh/" + ref
   355→		}
   356→		_, owner, repo, err := parseMirrorCloneRef(ref)
   357→		if err != nil {
   358→			return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID: %w", value, err)
   359→		}
   360→		return explainRepoRef{owner: owner, repo: repo}, nil
   361→	}
   362→	if !looksLikeULID(v) {
   363→		return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID (ULID)", value)
   364→	}
   365→	return explainRepoRef{repoID: v}, nil
   366→}
