   368→// resolveExplainRepoID resolves a raw repo ULID to its owner/name via the
   369→// control plane's repo index (exact-match by ID against the full index, the
   370→// same matching `entire search --repo <id>` uses).
   371→func resolveExplainRepoID(cmd *cobra.Command, repoID string) (owner, repo string, err error) {
   372→	var fullName string
   373→	err = runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
   374→		index, err := c.ListRepos(ctx, coreapi.ListReposParams{})
   375→		if err != nil {
   376→			return fmt.Errorf("list repositories: %w", err)
   377→		}
   378→		_, matched := resolveRepoFilters([]string{repoID}, index.Repos)
   379→		if len(matched) == 0 {
   380→			return fmt.Errorf("no repository with ID %q visible from your login", repoID)
   381→		}
   382→		fullName = matched[0].FullName
   383→		return nil
   384→	})
   385→	if err != nil {
   386→		return "", "", err
   387→	}
   388→	owner, repo, ok := strings.Cut(strings.ToLower(fullName), "/")
   389→	if !ok || owner == "" || repo == "" {
   390→		return "", "", fmt.Errorf("repository %q has an unexpected full name %q (want owner/name)", repoID, fullName)
   391→	}
   392→	return owner, repo, nil
   393→}
