   395→// explainRepoIsCurrent reports whether owner/repo names the same repository as
   396→// the cwd worktree's origin remote (handles ssh, https, and entire:// mirror
   397→// URL forms). Best-effort: any lookup or parse failure returns false, so
   398→// explain proceeds with the cross-repo fetch path.
   399→func explainRepoIsCurrent(ctx context.Context, owner, repo string) bool {
   400→	rawURL, err := gitremote.GetRemoteURL(ctx, "origin")
   401→	if err != nil {
   402→		return false
   403→	}
   404→	info, err := gitremote.ParseURL(rawURL)
   405→	if err != nil {
   406→		return false
   407→	}
   408→	return strings.EqualFold(info.Owner, owner) && strings.EqualFold(info.Repo, repo)
   409→}
