   168→+// validateExplainFlags enforces the flag-combination rules that
   169→+// MarkFlagsMutuallyExclusive cannot express: target requirements and
   170→+// value-range checks.
   171→+func validateExplainFlags(cmd *cobra.Command, v explainFlagValues, positional string) error {
   172→+	// --generate and --raw-transcript need a specific target — either the
   173→+	// positional arg, --checkpoint/-c, or --commit (which forwards to
   174→+	// the checkpoint path via the commit's Entire-Checkpoint trailer).
   175→+	hasCheckpointTarget := v.checkpoint != "" || v.commit != "" || positional != ""
   176→+	if v.generate && !hasCheckpointTarget {
   177→+		return errors.New("--generate requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
   178→+	}
   179→+	if v.force && !v.generate {
   180→+		return errors.New("--force requires --generate flag")
   181→+	}
   182→+	if v.rawTranscript && !hasCheckpointTarget {
   183→+		return errors.New("--raw-transcript requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
   184→+	}
   185→+	if v.transcript && !hasCheckpointTarget {
   186→+		return errors.New("--transcript requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag")
   187→+	}
   188→+	if cmd.Flags().Changed("session-index") {
   189→+		if !v.transcript && !v.rawTranscript {
   190→+			return errors.New("--session-index only applies with --transcript or --raw-transcript")
   191→+		}
   192→+		if v.sessionIndex < 0 {
   193→+			return errors.New("--session-index must be non-negative")
   194→+		}
   195→+	}
   196→+	if cmd.Flags().Changed("limit") {
   197→+		if !v.json {
   198→+			return errors.New("--limit only applies with --json")
   199→+		}
   200→+		if v.listLimit <= 0 {
   201→+			return errors.New("--limit must be positive")
   202→+		}
   203→+	}
   204→+	// --repo names another repo whose checkpoint to fetch and explain.
   205→+	// It needs a specific checkpoint target: --commit resolves against
   206→+	// local history and --session filters the local list view, so
   207→+	// neither can be cross-repo (they're excluded via
   208→+	// MarkFlagsMutuallyExclusive in newExplainCmd, along with --generate,
   209→+	// which writes a summary the foreign repo would never see).
   210→+	if v.cluster != "" && v.repo == "" {
   211→+		return errors.New("--cluster requires --repo")
   212→+	}
   213→+	if v.repo != "" && positional == "" && v.checkpoint == "" {
   214→+		return errors.New("--repo requires a checkpoint ID (positional or --checkpoint/-c)")
   215→+	}
   216→+	// --summary-timeout-seconds only makes sense with --generate.
   217→+	if cmd.Flags().Changed("summary-timeout-seconds") {
   218→+		if !v.generate {
   219→+			return errors.New("--summary-timeout-seconds only applies with --generate")
   220→+		}
   221→+		if v.summaryTimeoutSeconds < 0 {
   222→+			return errors.New("--summary-timeout-seconds must be non-negative")
   223→+		}
   224→+	}
   225→+	return nil
   226→+}
