   411→// resolveExplainRepoFetchURL resolves the entire:// mirror URL to fetch a
   412→// foreign repo's checkpoint ref from: pullable placements via the core API
   413→// (the same authority `repo clone` uses), then the shared placement picker
   414→// with explain-specific wording and the --cluster escape hatch.
   415→func resolveExplainRepoFetchURL(cmd *cobra.Command, owner, repo, clusterFlag string) (string, error) {
   416→	placements, err := listPullablePlacements(cmd, owner, repo, clusterFlag)
   417→	if err != nil {
   418→		return "", err
   419→	}
   420→	if len(placements) == 0 {
   421→		return "", fmt.Errorf("no mirror found for gh/%s/%s; cross-repo explain fetches checkpoints from the repo's Entire mirror", owner, repo)
   422→	}
   423→	chosen, err := selectPlacement(cmd, placements, clusterFlag, placementPicker{
   424→		selector: "--cluster",
   425→		title:    "This repo is mirrored on more than one cluster — pick one to fetch the checkpoint from",
   426→		action:   "Explain",
   427→	})
   428→	if err != nil {
   429→		return "", err
   430→	}
   431→	// chosen.ClusterHost is server-provided but interpolated into the entire://
   432→	// URL like a user-supplied --cluster, so apply the same anti-token-leak
   433→	// guard before building it (see repo clone).
   434→	if err := validateClusterHost(chosen.ClusterHost); err != nil {
   435→		return "", fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
   436→	}
   437→	return mirrorCloneURL(chosen.ClusterHost, owner, repo), nil
