   503→+// foreignRepoFixture creates a bare repo holding (or not holding) a checkpoint
   504→+// ref — the "foreign repo's mirror" for FetchCheckpointRefFrom — plus a
   505→+// separate cwd work repo with no remotes, and chdirs into the work repo (the
   506→+// fetch lands objects in the cwd repo's store).
   507→+func foreignRepoFixture(t *testing.T, withRef bool) (workDir, bareDir string, ref plumbing.ReferenceName) {
   508→+	t.Helper()
   509→+	bareDir = t.TempDir()
