   518→+	testutil.GitCommit(t, seedDir, "foreign init")
   519→+
   520→+	ref = plumbing.ReferenceName("refs/entire/checkpoints/Z9/01KVBJCWYA4YW6J5M9GP655HZ9")
   521→+	if withRef {
   522→+		out, err = exec.CommandContext(t.Context(), "git", "-C", seedDir, "push", "--quiet", bareDir, "HEAD:"+ref.String()).CombinedOutput()
   523→+		require.NoError(t, err, "git push checkpoint ref: %s", out)
