   740→// and a separate local work repo, and chdirs into the local repo. Returns the
   741→// foreign repo path (usable directly as a fetch URL) and the checkpoint ID.
   742→func crossRepoFixture(t *testing.T) (foreignDir string, cid id.CheckpointID) {
