   752→
   753→	// checkpoint.Open resolves settings relative to cwd, so write the foreign
   754→	// checkpoint while chdir'd into the foreign repo.
   755→	t.Chdir(foreignDir)
   756→	foreignRepo, err := git.PlainOpen(foreignDir)
   757→	require.NoError(t, err)
   758→	stores, err := checkpoint.Open(context.Background(), foreignRepo, checkpoint.OpenOptions{})
   759→	require.NoError(t, err)
   760→	cid = id.CheckpointID("01KVBJCWYA4YW6J5M9GP655HZ9")
   761→	require.NoError(t, stores.Persistent.Write(context.Background(), checkpoint.Session{
   762→		CheckpointID: cid,
   763→		SessionID:    "foreign-session",
   764→		Strategy:     "manual-commit",
   765→		Transcript:   redact.AlreadyRedacted([]byte(`{"type":"user","message":{"role":"user","content":"do the foreign thing"}}`)),
   766→		Prompts:      []string{"do the foreign thing"},
   767→		FilesTouched: []string{"a.go"},
   768→		AuthorName:   "Foreign Author",
   769→		AuthorEmail:  "foreign@example.com",
   770→	}))
   771→
   772→	localDir := t.TempDir()
   773→	testutil.InitRepo(t, localDir)
