	testutil.GitCommit(t, workDir, "init")
	out, err = exec.CommandContext(t.Context(), "git", "-C", workDir, "remote", "add", "upstream", bareDir).CombinedOutput()
	require.NoError(t, err, "git remote add upstream: %s", out)
	t.Chdir(workDir)

